    plate(p, rect(m2Window[0] - 4, m2Window[1] - 4, m2Window[2] + 4, m2Window[3] + 4), 44, 1);
    G.circle(p, [45.05, m2Window[2] - 6, (m2Window[1] + m2Window[3]) / 2], 2.5, [1, 0, 0], {role: 'detail', segments: 24});
  });

